  Lemma x2_p1b : forall m1 h maxW rs0a nz rs0d sorted rv0 rv cells jdt jrest SYj RVj
      (q32 q48 q56 q64 q72 q80 q88 q96 q112 q120 q128 q136 q144 : word) (T0 : Z) (x1 x5 x6 x7 x8 x10 x12 x14 x16 x17 x18 x19 x20 x21 x22 x26 x27 x29 x30 x31 : word),
    read_stats src = Ok h -> X2PATH mtl h maxW rs0a nz rs0d sorted rv0 rv cells -> 1 <= mtl <= 12 ->
    1 <= hs_ret h <= 129 ->
