    rw_cells psegs m1 (FB + 16) [C8 (Z_to_bv 64 mtl); C8 (Z_to_bv 64 (hs_ret h)); C8 q32; C8 (Z_to_bv 64 DT)] ->
    rw_cells psegs m1 (FB + 48) [C8 q48; C8 q56; C8 q64; C8 q72; C8 q80; C8 q88; C8 q96; C8 (Z_to_bv 64 (tl + 1));
