    rw_cells psegs m1 (FB + 160) [C4 (Z_to_bv 64 (hs_nbSymbols h)); C4 (Z_to_bv 64 tl)] ->
    rw_cells psegs m1 (FB + 168) [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk psegs m1 lo FB -> wr_at psegs m FB 168 ->
    munch WALL m m1 -> wmono psegs m m1 -> mem_inv psegs m1 ->
    evt psegs POST (MS (mkR x1 (Z_to_bv 64 FB) gp tp x5 x6 x7 x8 (Z_to_bv 64 (W + 992)) x10 (Z_to_bv 64 (W + 680)) x12 (Z_to_bv 64 (tl - maxW + 1)) x14 (Z_to_bv 64 (W + 676)) x16 x17 x18 x19 x20 x21 x22 (Z_to_bv 64 T0) (Z_to_bv 64 (mtl * 16777217)) (Z_to_bv 64 W) x26 x27 (Z_to_bv 64 tl) x29 x30 x31) F (Z_to_bv 64 0x13b60) fc None m1 (seg_rom psegs)).
