  (* [comment removed for export] *)
  Lemma x2_p1 : forall m1 h jdt jrest SYj RVj
      (q16 q24 q32 q40 q48 q56 q64 q72 q80 q88 q96 q104 q112 q120 q128 q136 q144 q152 : word) (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x20 x21 x22 x26 x27 x28 x29 x30 x31 : word),
    read_stats src = Ok h -> Forall (fun c => 0 <= c < 256) src -> 1 <= mtl <= 12 ->
    0 < DT -> DT + 4 * (1 + 2 ^ mtl) <= lo -> 0 < W -> W + 8704 <= lo -> lo <= SP - 4096 -> SP <= 2 ^ 47 ->
    (DT + 4 * (1 + 2 ^ mtl) <= W \/ W + 8704 <= DT) ->
    u8arr psegs m1 DT (le4 (Z_to_bv 64 (mtl * 16777217))) ->
    u8arr psegs m1 (DT + 4) jdt -> length jdt = Z.to_nat (4 * 2 ^ mtl) ->
    u8arr psegs m1 (W + 992) (map (Z_to_bv 8) (hs_weights h) ++ jrest) -> zlen jrest = 256 - hs_nbSymbols h ->
    u32arr psegs m1 (W + 624) (map (Z_to_bv 64) (hs_rank h)) ->
    u32arr psegs m1 (W + 676) (map (Z_to_bv 64) (repeat 0 15)) ->
    u8arr psegs m1 W RVj -> length RVj = 624%nat ->
